from taf.internal.robot_typecasts import time_to_seconds, to_boolean

from ..util import wrap_result


class SoftwareUpdateInterface(object):

    def update_software(self, sw_package, should_activate=True, timeout=600):
        """Perform software update.

        :param string sw_package: Path to software package.
        :param boolean should_activate: Activate software flag.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        should_activate = to_boolean(should_activate)

        self._api_client.execute_procedure(
            "softwareUpdate", {"shouldActivate": should_activate}, timeout, input_file_name=sw_package)

    def download_and_update_software(self, url, target_bd, should_activate=True, timeout=600):
        """Download software package and perform update.

        :param string url: File server URL.
        :param string target_bd: Remote path to software package.
        :param boolean should_activate: Activate software flag.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        str(url)
        str(target_bd)

        should_activate = to_boolean(should_activate)
        timeout = time_to_seconds(timeout)

        self._api_client.execute_procedure(
            "softwareUpdate", {"fileServerUrl": url, "targetBd": target_bd, "shouldActivate": should_activate}, timeout)

    def rollback_software(self, timeout=300):
        """Perform software rollback.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: string
        :return: software rollback status
        """
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_procedure("swRollback", {}, timeout)

    def abort_software_update(self, timeout=60):
        """Abort software update.

        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        self._api_client.execute_procedure("swDownloadAbort", {}, timeout)

    @wrap_result
    def get_software_info(self, timeout=10):
        """Get software info.

        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: list
        :return: list of active software.
        """
        timeout = time_to_seconds(timeout)
        return self._api_client.execute_infomodel_request("swInfo", {"dataType": "swView"}, timeout)
